import type { ReactNode } from 'react';
import { cn } from '@/utils/cn';

// 디자인 시스템 아이콘 (Figma "UI for JY (11.20)" > Icon 160:15417, SVG로 내보낸 모양 그대로)
// - 색은 모두 currentColor: 감싼 요소의 글자색을 따른다 (text-grey-6 등으로 정한다)
//   각 아이콘 위 주석의 "시안 색"은 시안에서 주로 쓰인 색 (참고용)
// - 기본 크기는 시안 크기 (size-6 = 24, size-4.5 = 18)
// - 18·24 두 크기가 있는 아이콘
//   느낌표(Notice)·점 3개(ThreadDots): 크기마다 그림 비율이 달라서 size={18}로 18 그림을 고른다
//   닫기(Close): 18은 24를 그대로 줄인 모양이라 className="size-4.5"로 줄인다
//   체크박스(CheckBox): 18(빈 칸/체크)은 CheckBoxIcon, 24(체크만, 성공 토스트)는 CheckBoxFilledIcon

interface IconProps {
  className?: string;
}

interface SizedIconProps extends IconProps {
  size?: 18 | 24;
}

function Icon({
  className,
  size = 24,
  children,
}: IconProps & { size?: 18 | 24; children: ReactNode }) {
  return (
    <svg
      viewBox={`0 0 ${size} ${size}`}
      className={cn(size === 24 ? 'size-6' : 'size-4.5', 'shrink-0', className)}
      fill="none"
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

